create_new_dropbox_text_file.beforeRequest:
var flag = (value) => value === '' ? undefined : value === 'true';
request.headers['Dropbox-API-Arg'] = JSON.stringify({autorename: flag(inputs.autorename), path: inputs.path, mode: 'add', mute: flag(inputs.mute), strict_conflict: flag(inputs.strict_conflict)});
return request;

upload_dropbox_file.beforeRequest:
var encode = (value) => JSON.stringify(value).replace(/[\u007f-\uffff]/g, (character) => '\\u' + ('000' + character.charCodeAt(0).toString(16)).slice(-4));
var flag = (value) => value === '' ? undefined : value === 'true';
request.headers['Dropbox-API-Arg'] = encode({autorename: flag(inputs.autorename), path: inputs.path, mode: 'add', mute: flag(inputs.mute), strict_conflict: flag(inputs.strict_conflict)});
return request;

lock_dropbox_file.afterResponse:
var entry = (response.entries || [])[0];
if (!entry) throw new Error('Dropbox gave no result for the file.');
if (entry['.tag'] === 'failure') throw new Error('Dropbox could not lock the file: ' + JSON.stringify(entry.failure));
return entry;

unlock_dropbox_file.afterResponse:
var entry = (response.entries || [])[0];
if (!entry) throw new Error('Dropbox gave no result for the file.');
if (entry['.tag'] === 'failure') throw new Error('Dropbox could not unlock the file: ' + JSON.stringify(entry.failure));
return entry;

get_dropbox_file_lock.afterResponse:
var entry = (response.entries || [])[0];
if (!entry) throw new Error('Dropbox gave no result for the file.');
if (entry['.tag'] === 'failure') throw new Error('Dropbox could not read the lock of the file: ' + JSON.stringify(entry.failure));
return entry;

list_dropbox_folder.beforeRequest:
var root = inputs.path.trim() === '/' || inputs.path.trim() === '';
request.body = {path: root ? '' : inputs.path, recursive: inputs.recursive === '' ? undefined : inputs.recursive === 'true', limit: Math.min(Number(inputs.limit) || 2000, 2000)};
return request;

list_dropbox_folder.afterResponse:
var limit = Number(inputs.limit) || 2000;
var page = response;
var entries = page.entries;
while (page.has_more && entries.length < limit) {
  page = call({method: 'POST', url: '/files/list_folder/continue', headers: {'Content-Type': 'application/json'}, body: {cursor: page.cursor}});
  entries = entries.concat(page.entries);
}
return Object.assign({}, page, {entries: entries});

search_dropbox.beforeRequest:
var split = (text) => text.split(',').map((part) => part.trim()).filter((part) => part.length > 0);
var orNothing = (items) => items.length > 0 ? items : undefined;
var root = inputs.path.trim() === '/' || inputs.path.trim() === '';
request.body = {query: inputs.query, options: {
  path: root ? '' : inputs.path,
  max_results: Number(inputs.max_results) || 100,
  order_by: inputs.order_by === 'modified_time' ? 'last_modified_time' : inputs.order_by || undefined,
  file_status: inputs.file_status || undefined,
  filename_only: inputs.filename_only === '' ? undefined : inputs.filename_only === 'true',
  file_extensions: orNothing(split(inputs.file_extensions).map((part) => part.replace(/^\./, '')).filter((part) => part.length > 0)),
  file_categories: orNothing(split(inputs.file_categories).map((part) => part.toLowerCase())),
  account_id: inputs.account_id || undefined
}};
return request;

new_folder.beforeRequest:
if (memory.cursor) {
  request.body = {cursor: memory.cursor};
} else {
  request.url = '/files/list_folder/get_latest_cursor';
  var root = inputs.path.trim() === '/' || inputs.path.trim() === '';
  request.body = {path: root ? '' : inputs.path, recursive: inputs.recursive === 'true', include_deleted: false};
}
return request;

new_folder.afterResponse:
if (!memory.cursor) {
  memory.cursor = response.cursor;
  return [];
}
var page = response;
var folders = page.entries.filter((entry) => entry['.tag'] === 'folder');
while (page.has_more) {
  page = call({method: 'POST', url: '/files/list_folder/continue', body: {cursor: page.cursor}});
  folders = folders.concat(page.entries.filter((entry) => entry['.tag'] === 'folder'));
}
memory.cursor = page.cursor;
return folders;
